def solve(data):
    # Keep the latest revision of each identified event; ties go to the
    # event appearing later in the input. Events without IDs are all unique.
    selected = {}
    for position, event in enumerate(data['events']):
        if 'id' in event:
            key = ('id', event['id'])
            revision = event.get('revision', 0)
            rank = (revision, position)
            if key not in selected or rank >= selected[key][0]:
                selected[key] = (rank, event)
